package dev.cazajefes;
import java.util.*;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.inventory.*;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.potion.*;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.*;
/** PvP-only relics. Canceled damage never activates powers or consumes their cooldown. */
final class DuelRelics implements Listener {
 private record Key(UUID player,String power){}
 private record Activation(Player attacker,Player victim,String weapon,String offense,String defense){}
 private final CazaJefesPlugin plugin;private final RelicItems items;private final NamespacedKey item,projectile;
 private final Map<Key,Long> cooldowns=new HashMap<>();private final Map<UUID,DuelCatalog.Streak> streaks=new HashMap<>();private final Map<EntityDamageByEntityEvent,Activation> pending=new WeakHashMap<>();
 DuelRelics(CazaJefesPlugin plugin,RelicItems items){this.plugin=plugin;this.items=items;item=new NamespacedKey(plugin,"relic_id");projectile=new NamespacedKey(plugin,"duel_projectile");}
 private ItemStack named(Material material,String id,String name,TextColor color,String...description){ItemStack out=new ItemStack(material);var meta=out.getItemMeta();meta.displayName(Component.text("✦ "+name,color).decorate(TextDecoration.BOLD).decoration(TextDecoration.ITALIC,false));List<Component> lore=new ArrayList<>();for(String line:description)lore.add(Component.text(line,NamedTextColor.GRAY).decoration(TextDecoration.ITALIC,false));meta.lore(lore);meta.setEnchantmentGlintOverride(true);meta.getPersistentDataContainer().set(item,PersistentDataType.STRING,id);out.setItemMeta(meta);return out;}
 ItemStack material(DuelCatalog.Relic r){return named(r.icon(),"pvp_material_"+r.id(),r.material(),NamedTextColor.AQUA,"Material refinado · Forja de duelo","Afinidad: "+r.name(),"Se fabrica con núcleos, fragmentos y Rare Essence","Reacciona al poder de su reliquia; no es un drop nuevo");}
 ItemStack gear(DuelCatalog.Relic r){ItemStack out=named(r.gear(),"pvp_gear_"+r.id(),r.name(),RareAppearance.ORANGE,"ʀᴇʟɪQᴜɪᴀ ᴅᴇ ᴅᴜᴇʟᴏ · "+(r.armor()?"Defensa reactiva":"Arma táctica"),r.power(),"Recarga: "+r.cooldown()/1000+" s · Solo contra jugadores","Una defensa de armadura por impacto","Se forja una pieza nueva; no transfiere mejoras");var meta=out.getItemMeta();List<Component> lines=new ArrayList<>(meta.lore());lines.add(1,Component.text("✧ "+RareAppearance.title(r.id())+" I",RareAppearance.ORANGE).decoration(TextDecoration.ITALIC,false));meta.lore(lines);out.setItemMeta(meta);out.addUnsafeEnchantment(Enchantment.UNBREAKING,5);out.addUnsafeEnchantment(Enchantment.MENDING,1);if(r.armor())out.addUnsafeEnchantment(Enchantment.PROTECTION,7);else if(r.gear()==Material.BOW)out.addUnsafeEnchantment(Enchantment.POWER,5);else if(r.gear()==Material.CROSSBOW){out.addUnsafeEnchantment(Enchantment.QUICK_CHARGE,3);out.addUnsafeEnchantment(Enchantment.MULTISHOT,1);}else out.addUnsafeEnchantment(Enchantment.SHARPNESS,5);return out;}
 void registerRecipes(){for(var r:DuelCatalog.ALL){String m="pvp_material_"+r.id(),g="pvp_gear_"+r.id();Bukkit.removeRecipe(new NamespacedKey(plugin,m));Bukkit.removeRecipe(new NamespacedKey(plugin,g));items.addDuelRecipe(m,material(r),new String[]{" R ","FCF"," E "},Map.of('R',new RecipeChoice.MaterialChoice(r.reagent()),'F',new RecipeChoice.ExactChoice(items.fragment(1)),'C',items.coreChoice(),'E',new RecipeChoice.ExactChoice(items.essence())));items.addDuelRecipe(g,gear(r),new String[]{" M ","EKE"," B "},Map.of('M',new RecipeChoice.ExactChoice(material(r)),'E',new RecipeChoice.ExactChoice(items.essence()),'K',new RecipeChoice.ExactChoice(items.crystal(BossCatalog.Tier.EPIC,1)),'B',new RecipeChoice.MaterialChoice(r.gear())));}}
 private String power(ItemStack stack){String id=items.customId(stack);return id!=null&&id.startsWith("pvp_gear_")?id.substring(9):null;}
 private String weapon(EntityDamageByEntityEvent e,Player player){return e.getDamager() instanceof Projectile p?p.getPersistentDataContainer().get(projectile,PersistentDataType.STRING):power(player.getInventory().getItemInMainHand());}
 private boolean ready(Player p,String id,long now){return id!=null&&DuelCatalog.get(id)!=null&&DuelCatalog.ready(now,cooldowns.getOrDefault(new Key(p.getUniqueId(),id),0L));}
 private boolean allowed(Player a,Player v){if(a==v||!CombatGuard.eligible(a)||!CombatGuard.eligible(v)||!a.getWorld().equals(v.getWorld())||!a.getWorld().getPVP())return false;var team=a.getScoreboard().getEntryTeam(a.getName());return team==null||team.allowFriendlyFire()||!team.hasEntry(v.getName());}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void shoot(EntityShootBowEvent e){if(e.getEntity() instanceof Player){String id=power(e.getBow());if(id!=null&&List.of("ocaso","resonancia").contains(id)&&(!id.equals("ocaso")||e.getForce()>=.7f))e.getProjectile().getPersistentDataContainer().set(projectile,PersistentDataType.STRING,id);}}
 @EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true)public void prepare(EntityDamageByEntityEvent e){Entity source=e.getDamager();if(source instanceof Projectile shot&&shot.getShooter() instanceof Entity shooter)source=shooter;if(!(source instanceof Player a)||!(e.getEntity() instanceof Player v)||!allowed(a,v)||!DuelCatalog.validHit(e.isCancelled(),e.getFinalDamage()))return;long now=System.currentTimeMillis();boolean ranged=e.getDamager() instanceof Projectile;String weapon=weapon(e,a),offense=null,defense=null;boolean charged=a.getAttackCooldown()>=.9f;
  if(ready(a,weapon,now)&&!DuelCatalog.get(weapon).armor()&&DuelCatalog.condition(weapon,ranged,charged,a.getLocation().distanceSquared(v.getLocation()),false,1)&&(!weapon.equals("hemorragia")||streaks.computeIfAbsent(a.getUniqueId(),k->new DuelCatalog.Streak()).third(v.getUniqueId(),now)))offense=weapon;
  for(ItemStack piece:v.getInventory().getArmorContents()){String id=power(piece);if(ready(v,id,now)&&DuelCatalog.get(id).armor()&&DuelCatalog.condition(id,ranged,false,0,v.hasPotionEffect(PotionEffectType.SLOWNESS),v.getHealth()/Math.max(1,v.getMaxHealth()))){defense=id;break;}}
  if(offense!=null)SafeDamage.scale(e,DuelCatalog.multiplier(offense));if(defense!=null)SafeDamage.scale(e,DuelCatalog.multiplier(defense));pending.put(e,new Activation(a,v,charged&&!ranged?weapon:null,offense,defense));
 }
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void accepted(EntityDamageByEntityEvent e){Activation a=pending.remove(e);if(a==null||!DuelCatalog.validHit(e.isCancelled(),e.getFinalDamage()))return;long now=System.currentTimeMillis();if("hemorragia".equals(a.weapon()))streaks.computeIfAbsent(a.attacker().getUniqueId(),k->new DuelCatalog.Streak()).accepted(a.victim().getUniqueId(),now);if(a.offense()!=null){activate(a.attacker(),a.victim(),a.offense(),now);if(a.offense().equals("hemorragia"))streaks.get(a.attacker().getUniqueId()).consume();}if(a.defense()!=null)activate(a.victim(),a.attacker(),a.defense(),now);}
 private void activate(Player owner,Player opponent,String id,long now){cooldowns.put(new Key(owner.getUniqueId(),id),now+DuelCatalog.get(id).cooldown());switch(id){case "hemorragia"->opponent.addPotionEffect(new PotionEffect(PotionEffectType.WITHER,40,0));case "fractura"->opponent.addPotionEffect(new PotionEffect(PotionEffectType.WEAKNESS,40,0));case "ocaso"->{opponent.addPotionEffect(new PotionEffect(PotionEffectType.BLINDNESS,20,0));opponent.addPotionEffect(new PotionEffect(PotionEffectType.GLOWING,60,0));}case "resonancia"->opponent.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS,40,0));case "vigia"->opponent.addPotionEffect(new PotionEffect(PotionEffectType.GLOWING,40,0));case "quitina"->owner.addPotionEffect(new PotionEffect(PotionEffectType.RESISTANCE,40,0));case "cadenas"->{owner.removePotionEffect(PotionEffectType.SLOWNESS);owner.addPotionEffect(new PotionEffect(PotionEffectType.SPEED,40,0));}case "espectral"->owner.addPotionEffect(new PotionEffect(PotionEffectType.SPEED,60,1));default->{}}
  owner.sendActionBar(Component.text("✦ "+DuelCatalog.get(id).name()+" · "+DuelCatalog.get(id).cooldown()/1000+" s",RareAppearance.ORANGE).decorate(TextDecoration.BOLD));owner.playSound(owner.getLocation(),Sound.BLOCK_AMETHYST_BLOCK_CHIME,.6f,1.2f);for(int i=0;i<12;i++){double angle=i*Math.PI/6;CosmeticFX.to(owner,Particle.DUST,owner.getLocation().add(Math.cos(angle),.8,Math.sin(angle)),1,0,0,0,0,new Particle.DustOptions(Color.ORANGE,1));}}
 @EventHandler(priority=EventPriority.HIGHEST)public void prepareCraft(org.bukkit.event.inventory.PrepareItemCraftEvent event){if(!(event.getRecipe() instanceof ShapedRecipe recipe)||!recipe.getKey().getNamespace().equals("cazajefes")||!recipe.getKey().getKey().startsWith("pvp_"))return;for(ItemStack stack:event.getInventory().getMatrix())if(items.customId(stack)!=null&&recipe.getChoiceMap().values().stream().noneMatch(choice->choice instanceof RecipeChoice.ExactChoice&&choice.test(stack))){event.getInventory().setResult(null);return;}}
 @EventHandler public void quit(PlayerQuitEvent e){UUID id=e.getPlayer().getUniqueId();streaks.remove(id);plugin.getServer().getScheduler().runTaskLater(plugin,()->{long now=System.currentTimeMillis();cooldowns.entrySet().removeIf(entry->entry.getKey().player().equals(id)&&entry.getValue()<=now);},400L);}
 void stop(){cooldowns.clear();streaks.clear();pending.clear();}
}
